{"results": [{"id": "FAM:SF-APPM-058", "label": "Study family SF-APPM-058: PNR shot-level season rates vs possession labels", "score": 1.58, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-058 (0.85)"], "attributes": {"observed_research_question": "PNR shot-level season rates vs possession labels", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "PBP-derived shot-level PNR rates sit in a realistic band (script notes possession-level rates will be higher) and vary by team as expected.", "observed_result": "2024-25 shot-level PNR share of half-court shots ranges from OKC 7.567% (498/6581) and BOS 7.854% to IND 13.824% (856/6192) and NYK 11.959%. ATL 11.361%, DEN 11.404%, PHX 10.232% (bh 7.050 / roll 3.181).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No pass/fail gate in the output; rates are a calibration input for PBPProxyPNR (later logs show calibrated PNR ~17.9-19.6% of possessions).", "observed_sample_and_power": "30 teams, half_court_shots ~5994-6581", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPM-014"}]}, {"id": "FAM:SF-APPS-058", "label": "Study family SF-APPS-058: Observed on-ball defensive scheme labels (ORL-DET G1)", "score": 1.542, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-058 (0.80)"], "attributes": {"observed_research_question": "Observed on-ball defensive scheme labels (ORL-DET G1)", "auto_outcome_status": "untestable", "observed_hypothesis": "NBA matchup/PBP fields can label on-ball coverage (DROP/ICE/SWITCH) at usable rates.", "observed_result": "DET: 67 on-ball HC poss, 10 labeled (14.9%) ? DROP n=5 PPP=1.20, ICE_CANDIDATE n=5 PPP=0.80, OTHER n=57 PPP=1.42. ORL: 60 poss, 2 labeled (3.3%). switches_on unpopulated.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Confident label rates 14.9% and 3.3%; NBA matchups feed did not populate switches_on.", "observed_sample_and_power": "n=67/60 possessions, 10/2 labeled", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "failed_gate"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPM-016", "label": "Study family SF-APPM-016: Possession-level SQ2 test: engine recommended PT (playoff series)", "score": 1.182, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-016 (0.80)"], "attributes": {"observed_research_question": "Possession-level SQ2 test: engine recommended PT (playoff series)", "auto_outcome_status": "rejected", "observed_hypothesis": "Possessions on the engine's recommended PT score more than other PTs within the series, beyond inherent PT PPP.", "observed_result": "A +0.140 PPP [0.084,0.196]; B DiD +0.090 [0.041,0.141]; C gamma +0.0088 SE 0.0239 p=0.7139.", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Strictest FE test gamma +0.0088, p=0.71; A/B explained by engine picking high-PPP PTs.", "observed_sample_and_power": "504 cells, SE 0.0239 (iid)", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "74 team-series pairs; Test A literal, Test B DiD vs RS, Test C two-way FE OLS on 504 cells.", "observed_verdict": "null", "observed_failure_type": "B_powered_null", "observed_notes": "NOT_RECORDED", "auto_confidence": "high (0.95)"}, "relationships": []}, {"id": "FAM:SF-APPS-010", "label": "Study family SF-APPS-010: Play-type PPP change across playoff series game buckets", "score": 1.052, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-010 (0.81)", "request matches VAR:PPP_points_per_possession (0.79); FAM:SF-APPS-010 auto_measures VAR:PPP_points_per_possession"], "attributes": {"observed_research_question": "Play-type PPP change across playoff series game buckets", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Play-type PPP (especially DRIVE) declines as a playoff series progresses, so DRIVE is a good early-series call.", "observed_result": "DRIVE 0.889 -> 0.949 (+0.060); CUT +0.114; PNR +0.087; PULL_UP -0.077; POST_UP -0.032.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "'NO CLEAR SIGNAL - DRIVE PPP is stable or improves across the series'; observational with selection caveats.", "observed_sample_and_power": "1197 records; no CIs", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Pooled (series, team, PT, bucket) records (1197), EARLY G1-2 / MID G3-4 / LATE G5-7, min 10 poss, min 3 series.", "observed_verdict": "null", "observed_failure_type": "E_unclear"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}]}, {"id": "FAM:SF-CHT-009", "label": "Study family SF-CHT-009: Superstar suppression by lineup and forced play type", "score": 0.844, "reached_via": ["request matches RQC:RQC-083 (0.74); FAM:SF-CHT-009 auto_addresses_question RQC:RQC-083", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.75); FAM:SF-CHT-009 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Superstar suppression by lineup and forced play type", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Named star initiators have identifiable lineup and forced-play-type suppressors in the possession graph.", "observed_result": "Jokic vs MIN lineup PPP 0.814, -0.385 (n=59); Curry vs HOU 0.851, -0.358 (n=47); Doncic vs LAC 0.733, -0.396 (n=30); Giannis forced PULL_UP 0.848, -0.540 vs preferred DRIVE (largest gap).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No placebo or matching; later sequence work treated similar star-chain gaps as artifacts.", "observed_sample_and_power": "n>=30 for lineup cells cited", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Jokic/Curry/Doncic/Giannis; min-15 gate on 8 play types; opposing DEFENSE_LINEUP ~84% coverage; 272-row CSV."}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}]}, {"id": "FAM:SF-APPM-014", "label": "Study family SF-APPM-014: Play-type label accuracy / distribution audit", "score": 0.802, "reached_via": ["FAM:SF-APPM-058 auto_related_family (record_link_related_to) FAM:SF-APPM-014", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.75); FAM:SF-APPM-014 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Play-type label accuracy / distribution audit", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Inferred play-type labels match benchmark volumes, foul rates, PPP and known team identities.", "observed_result": "Audit overall FAIL: OTHER 20.2% vs <10% target; 40.8% low confidence; DRIVE foul-draw 1.7% vs 14-22% benchmark; most PTs PPP above benchmark band; MIA identity checks fail.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "'play type labels have systematic issues that undermine adaptation findings'; foul possessions leak into OTHER.", "observed_verdict": "tool_eval_fail"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:leakage"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:LEAKAGE_LOOKAHEAD"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPA-030", "label": "Study family SF-APPA-030: Play-type label backfill verification", "score": 0.778, "reached_via": ["FAM:SF-APPS-058 auto_related_family (limitation_precedent) FAM:SF-APPA-030", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.75); FAM:SF-APPA-030 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Play-type label backfill verification", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Backfilled play-type labels match expected league distributions and team identities.", "observed_result": "PNR 28.7% FAIL (band 20-28%); PULL_UP 7.9% FAIL; 3100 games with team PNR >33% FAIL; PNR PPP 0.948 PASS; temporal PASS; team identity FAIL; 2024-25 PULL_UP ~0-1% for many teams. Final: FAIL.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "2024-25 PULL_UP shares 0.0-2.0% for many teams; 82.8% of PNR labels proxy_calibrated.", "observed_sample_and_power": "921,514 possessions", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-001"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-005"}]}, {"id": "FAM:SF-CHT-025", "label": "Study family SF-CHT-025: Play-type labeling audit: OTHER/DRIVE foul leakage", "score": 0.713, "reached_via": ["request matches RQC:RQC-087 (0.74); FAM:SF-CHT-025 auto_addresses_question RQC:RQC-087", "request matches VAR:PPP_points_per_possession (0.79); FAM:SF-CHT-025 auto_measures VAR:PPP_points_per_possession"], "attributes": {"observed_research_question": "Play-type labeling audit: OTHER/DRIVE foul leakage", "auto_outcome_status": "artifact", "observed_hypothesis": "Play-type PPP differences are real efficiency, not labeling/foul artifacts.", "observed_result": "OTHER: 36% end in fouls, PPP inflated (FOUL_BUCKET). DRIVE: 12pp below foul benchmark (FOUL_LEAK). PNR shows 22% foul rate. Only 335 of 50,668 possessions (0.7%) map to a real play type via initiation_type.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "OTHER PPP inflated by 36% foul endings; DRIVE 12pp below foul benchmark; initiation_type maps 0.7%.", "observed_sample_and_power": "50,668 possessions in the initiation_type check", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Per-PT diagnostic of foul-ending share vs PPP; initiation_type mapping.", "observed_verdict": "artifact_found"}, "relationships": []}, {"id": "FAM:SF-APPA-001", "label": "Study family SF-APPA-001: A1 adaptation falsification: asymmetry, confidence and carryover tests", "score": 0.66, "reached_via": ["FAM:SF-APPS-058 auto_related_family (limitation_precedent) FAM:SF-APPA-001", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.75); FAM:SF-APPA-001 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "A1 adaptation falsification: asymmetry, confidence and carryover tests", "auto_outcome_status": "artifact", "observed_hypothesis": "If the A1 adapter PPP lift is real coverage response, wrong-way teams should do worse than no-signal teams, the gap should widen with scheme-vote confidence, and adapting in Game N should carry over to Game N+1.", "observed_result": "T1 dPPP: adapter +0.0667 (n=205), neutral +0.0248 (n=50), no_signal +0.1260 (n=57), wrong_way +0.0111 (n=274). T2: adapter minus no-signal -0.0361 (1 vote), -0.1170 (2 votes). T3 next-game PPP Welch t=-1.003, p=0.842; MW [cut; read_family for the full text]", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}, {"id": "FAM:SF-APPA-058", "label": "Study family SF-APPA-058: Season stability of top suppressors and negative teammate pairs", "score": 0.481, "reached_via": ["request matches RQC:RQC-044 (0.76); FAM:SF-APPA-058 auto_addresses_question RQC:RQC-044"], "attributes": {"observed_research_question": "Season stability of top suppressors and negative teammate pairs", "auto_outcome_status": "rejected", "observed_hypothesis": "Each star's top sequential suppressor is stable across seasons, and some teammate X->Y sequences have large negative premiums.", "observed_result": "2/30 (7%) stable (>=75% same top suppressor): D. Mitchell PUTBACK 75%, L. James POST_UP 75%. Negative: J. Tatum->K. Porzingis DRIVE->SPOT_UP -0.444 n=31; Giannis->Lillard DRIVE->PNR -0.263 n=31; J. Brown->J. Tatum SPOT_U [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Only 2/30 stars meet the 75% same-top-suppressor stability rule.", "observed_sample_and_power": "30 stars x 4 seasons; min n=20/cell", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}], "n_results": 10}

Stage 2. Using the retrieval result above (follow-up tools are allowed within the tool budget), complete steps 4 to 9
and reply with the final action. Output schema (all fields required):
{
 "research_concepts": [
  "concept"
 ],
 "methodological_questions": [
  "question"
 ],
 "historical_evidence": [
  {
   "id": "identifier of a record returned by a tool",
   "status_as_recorded": "outcome status exactly as stated in the record (supported | rejected | inconclusive | untestable | artifact | not a hypothesis test | no result recorded)",
   "finding": "what the record states, in its own terms"
  }
 ],
 "failed_approaches": [
  {
   "id": "identifier of a returned record",
   "what_failed": "approach",
   "why": "failure mechanism or limitation as recorded"
  }
 ],
 "evidence_establishes": [
  "what the retrieved evidence establishes for this question"
 ],
 "evidence_does_not_establish": [
  "what it leaves open or cannot show"
 ],
 "own_inferences": [
  "your inference, not stated in any record"
 ],
 "uncertainties": [
  "uncertainty or missing information"
 ],
 "historical_effect": {
  "changed_decision": "yes | no | no_historical_evidence",
  "explanation": "whether and how the historical evidence changed the decision"
 },
 "testability": {
  "p_testable": "number in [0,1]: probability the question can be answered with the stated data at useful power",
  "blocking_constraints": [
   {
    "code": "one of RISK_CODES",
    "text": "string"
   }
  ]
 },
 "prior_work": {
  "already_answered": "yes | partly | no | unknown",
  "cited": [
   "identifiers of prior work relied on"
  ],
  "summary": "string"
 },
 "risks": [
  {
   "code": "one of RISK_CODES",
   "text": "string"
  }
 ],
 "predicted_outcome": {
  "supported": "probability",
  "rejected": "probability",
  "untestable": "probability",
  "artifact": "probability",
  "uncertain": "probability"
 },
 "decision": "proceed | proceed_with_changes | do_not_proceed",
 "design": {
  "estimand": "string",
  "unit": "string",
  "sample": "string",
  "power": "string",
  "controls": "string",
  "falsification": "string",
  "multiplicity": "string",
  "decision_rule": "string",
  "data_version": "string"
 }
}
Field guidance:
- historical_evidence and failed_approaches: only records returned by a tool, with the status as recorded; empty lists
  if nothing relevant was returned.
- testability.p_testable: probability that the question can be answered with the stated data at useful statistical power.
- prior_work.already_answered: whether retrieved earlier work already answered substantially the same question.
  Use "unknown" if no earlier work was retrieved. List identifiers you relied on in prior_work.cited.
- predicted_outcome: probabilities (summing to 1) of what a competent test of the question as posed would conclude:
  supported, rejected (adequately powered null), untestable (cannot be tested with this data), artifact (apparent
  effect produced by a flaw), uncertain (inconclusive or inadequately tested).
- decision: proceed, proceed_with_changes (state the changes in design), or do_not_proceed.
- design: a pre-registration-quality plan even if the decision is do_not_proceed (then describe the minimum viable test).
